# modules/azure-resource-group/variables.tf
variable "name" {
  type        = string
  description = "Name of the resource group"
}

variable "location" {
  type        = string
  description = "Azure region"
}

variable "tags" {
  type        = map(string)
  description = "Tags to apply to the resource group"
  default     = {}
}

# root module call
module "payments_rg" {
  source   = "./modules/azure-resource-group"
  name     = "rg-payments-prod"
  location = "eastus2"
  tags = {
    environment = "prod"
  }
}

terraform {
  backend "azurerm" {
    resource_group_name  = "rg-tfstate"
    storage_account_name  = "stltvtfstateprod"
    container_name        = "tfstate"
    key                   = "payments/prod.terraform.tfstate"
  }
}

resource "azurerm_kubernetes_cluster" "this" {
  name                = "aks-payments-prod"
  location            = azurerm_resource_group.this.location
  resource_group_name  = azurerm_resource_group.this.name
  dns_prefix          = "payments-prod"

  default_node_pool {
    name       = "system"
    node_count = 2
    vm_size    = "Standard_D2s_v5"
  }

  identity {
    type = "SystemAssigned"
  }
}

resource "azurerm_kubernetes_cluster_node_pool" "workloads" {
  name                  = "workloads"
  kubernetes_cluster_id = azurerm_kubernetes_cluster.this.id
  vm_size               = "Standard_D4s_v5"
  enable_auto_scaling   = true
  min_count             = 2
  max_count             = 8
  node_count            = 2
}
